sort_ints(a, 5);
CHECK(a[0] == 1 && a[1] == 3 && a[2] == 3 && a[4] == 9);
CHECK_EQ(find_int(a, 5, 3) >= 1 && find_int(a, 5, 3) <= 2, 1);  /* any of the two */
CHECK_EQ(find_int(a, 5, 4), -1);
CHECK_EQ(find_int(a, 0, 1), -1);
double d[] = {2.5, -1.0, 0.0};
sort_doubles(d, 3);
CHECK(d[0] == -1.0 && d[2] == 2.5);
